from ute_common_abstract_core.aliases_registry import aliases_registry


def _get_info_and_log_it(ue_alias, info_type, timeout=None):
    """
    This function will be used in own-keywords.
    :param ue_alias: string
    :param info_type: string, one of values ['IMSI', 'IMEI', 'UE_OS_VER', 'DEVICE_MODEL', 'LAC', 'MCC', 'MNC', 'PCI',
         'CELL_ID', 'IP', 'SIGNAL_STRENGTH']
    :param timeout: string (with int content) or int or None - number of SECONDS
    :return: string - Specified info-type of UE specified by its ue-alias.
    """
    ue = aliases_registry()[ue_alias]
    result = ue.get_info(info_type, timeout)
    print("UE %s has info %s = %s" % (ue_alias, info_type, result))
    return result


def ensure_that_signal_strength_is_better_than(ue_alias, signal_strength_limit, timeout=None):
    """
    Raises exception if signal strength of given UE is <= than given signal_strength_limit.
    :param ue_alias:
    :param signal_strength_limit:
    :param timeout:
    """
    signal_strength = int(_get_info_and_log_it(ue_alias, 'SIGNAL_STRENGTH', timeout))
    signal_strength_limit = int(signal_strength_limit)
    if signal_strength <= signal_strength_limit:
        raise Exception("Expected signal is worse than %d, but current signal strength is %d" % (signal_strength_limit, signal_strength))
    print('Signal strength for UE %s - %d is better than %d (given limit)' % (ue_alias, signal_strength, signal_strength_limit))


def ensure_that_ues_have_the_same_cell(ue_alias1, ue_alias2, timeout=None):
    """
    Raises exception if two given ues has different cell ids.
    :param ue_alias1:
    :param ue_alias2:
    :param timeout:
    """
    cell_id1 = _get_info_and_log_it(ue_alias1, 'CELL_ID', timeout)
    cell_id2 = _get_info_and_log_it(ue_alias2, 'CELL_ID', timeout)
    if cell_id1 is not cell_id2:
        raise Exception("Expected same cell ids, but: %s != %s" % (cell_id1, cell_id2))
    print('succeed check UEs %s and %s has same cell id %s' % (ue_alias1, ue_alias2, cell_id1))
